/* Layout: team-grid — structure only, pure DS tokens */
.l-team-grid {
  padding: var(--spacing-20) var(--spacing-8);
}

.l-team-grid__header {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  margin-bottom: var(--spacing-12);
}

.l-team-grid__tagline {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--muted-foreground);
  margin-bottom: var(--spacing-3);
}

.l-team-grid__heading {
  font-size: var(--font-size-4xl);
  line-height: var(--line-height-4xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--letter-spacing-tight);
  color: var(--foreground);
  margin-bottom: var(--spacing-5);
}

@media (min-width: 768px) {
  .l-team-grid__heading {
    font-size: var(--font-size-5xl);
    line-height: var(--line-height-5xl);
  }
}

@media (min-width: 1024px) {
  .l-team-grid__heading {
    font-size: var(--font-size-6xl);
    line-height: var(--line-height-6xl);
  }
}

.l-team-grid__description {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--muted-foreground);
}

@media (min-width: 768px) {
  .l-team-grid__description {
    font-size: var(--font-size-lg);
    line-height: var(--line-height-lg);
  }
}

.l-team-grid__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-12) var(--spacing-8);
}

@media (min-width: 768px) {
  .l-team-grid__grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-8) var(--spacing-12);
  }
}

.l-team-grid__member {
  display: flex;
  flex-direction: column;
  text-align: center;
}

.l-team-grid__member-media {
  position: relative;
  margin-bottom: var(--spacing-5);
  overflow: hidden;
  border-radius: var(--radius-lg);
}

@media (min-width: 768px) {
  .l-team-grid__member-media {
    margin-bottom: var(--spacing-6);
  }
}

.l-team-grid__member-media img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  display: block;
}

.l-team-grid__member-info {
  margin-bottom: var(--spacing-3);
}

@media (min-width: 768px) {
  .l-team-grid__member-info {
    margin-bottom: var(--spacing-4);
  }
}

.l-team-grid__member-name {
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-semibold);
  color: var(--foreground);
  margin-bottom: var(--spacing-1);
}

@media (min-width: 768px) {
  .l-team-grid__member-name {
    font-size: var(--font-size-lg);
  }
}

.l-team-grid__member-job {
  font-size: var(--font-size-sm);
  color: var(--muted-foreground);
}

.l-team-grid__member-bio {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground);
  margin-bottom: var(--spacing-6);
}

.l-team-grid__socials {
  display: flex;
  justify-content: center;
  gap: var(--spacing-3);
  align-self: center;
}

.l-team-grid__social {
  color: var(--foreground);
  display: inline-flex;
}

.l-team-grid__social:hover {
  color: var(--primary);
}

.l-team-grid__social svg {
  width: var(--spacing-6);
  height: var(--spacing-6);
}

.l-team-grid__hiring {
  max-width: 28rem;
  margin: var(--spacing-14) auto 0;
  text-align: center;
}

@media (min-width: 768px) {
  .l-team-grid__hiring {
    margin-top: var(--spacing-20);
  }
}

.l-team-grid__hiring-heading {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-2xl);
  font-weight: var(--font-weight-bold);
  color: var(--foreground);
  margin-bottom: var(--spacing-3);
}

@media (min-width: 768px) {
  .l-team-grid__hiring-heading {
    font-size: var(--font-size-3xl);
    line-height: var(--line-height-3xl);
    margin-bottom: var(--spacing-4);
  }
}

.l-team-grid__hiring-description {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--muted-foreground);
  margin-bottom: var(--spacing-6);
}

.l-team-grid__hiring-actions {
  display: flex;
  justify-content: center;
}

